function buildFullUrl(baseUrl, route) {
  const cleanBase = baseUrl.replace(/\/$/, "");
  if (!route || route === "/") {
    return cleanBase;
  }
  const cleanRoute = route.startsWith("/") ? route : `/${route}`;
  return `${cleanBase}${cleanRoute}`;
}

